// Pure calculations: all time and data enter through inputs.
function compute(inputs = {}) {
  const colors = { blue: '#00b6ee', green: '#07976b', amber: '#b77908', red: '#d62f54', gray: '#7890a6', neutral: '#315d7c' };
  const number = value => typeof value === 'number' && Number.isFinite(value) ? value : null;
  const level = number(inputs.level);
  const pressure = number(inputs.pressure);
  const flow = number(inputs.flow);
  const pump = value => {
    const code = number(value);
    const state = code === 1 ? 'Running' : code === 0 ? 'Stopped' : code === 2 ? 'Fault' : '--';
    const label = code === 1 ? 'Chạy' : code === 0 ? 'Dừng' : code === 2 ? 'Lỗi' : '--';
    return { state, label, running: code === 1, color: code === 1 ? colors.green : code === 2 ? colors.red : colors.gray };
  };
  const p01 = pump(inputs.p01), p02 = pump(inputs.p02);
  let mode = 'Mode: --';
  if (p01.state !== '--' && p02.state !== '--') {
    mode = p01.running && p02.running ? 'Mode: both pumps running' : p01.running ? 'Mode: normal' : p02.running ? 'Mode: degraded (P02 only)' : 'Mode: stopped';
  }
  const warnings = ['LOW_LEVEL', 'HIGH_LEVEL', 'HIGH_PRESSURE'];
  const critical = ['LOW_LOW_LEVEL', 'HIGH_HIGH_LEVEL', 'PUMP_FAULT'];
  const codes = typeof inputs.alarms === 'string' ? [...new Set(inputs.alarms.split(',').map(code => code.trim()).filter(Boolean))] : [];
  const names = { LOW_LEVEL: 'Mức nước thấp', LOW_LOW_LEVEL: 'Mức nước rất thấp', HIGH_LEVEL: 'Mức nước cao', HIGH_HIGH_LEVEL: 'Mức nước rất cao', HIGH_PRESSURE: 'Áp suất cao', PUMP_FAULT: 'Lỗi bơm' };
  const chips = codes.map(code => {
    const faultAssets = code === 'PUMP_FAULT' ? [p01.state === 'Fault' ? 'P01' : '', p02.state === 'Fault' ? 'P02' : ''].filter(Boolean).join(', ') : '';
    const severity = critical.includes(code) ? 'Critical' : warnings.includes(code) ? 'Warning' : '';
    return { text: (faultAssets ? faultAssets + ' – ' : '') + (names[code] || code) + (severity ? ' (' + severity + ')' : ''), color: critical.includes(code) ? colors.red : warnings.includes(code) ? colors.amber : colors.neutral };
  });
  if (!chips.length) chips.push({ text: typeof inputs.alarms === 'string' ? 'Không có cảnh báo' : '--', color: colors.neutral });
  const stamp = typeof inputs.timestamp === 'number' ? number(inputs.timestamp) : typeof inputs.timestamp === 'string' && inputs.timestamp.trim() ? Date.parse(inputs.timestamp) : NaN;
  const now = number(inputs.nowMs);
  const age = Number.isFinite(stamp) && now !== null ? Math.max(0, (now - stamp) / 1000) : null;
  const clamped = level === null ? 0 : Math.min(100, Math.max(0, level));
  return {
    level, waterHeight: clamped * 2.06, waterY: 676 - clamped * 2.06,
    waterColor: level === null ? colors.gray : level >= 90 || level <= 10 ? colors.red : level >= 85 || level <= 20 ? colors.amber : colors.blue,
    levelText: level === null ? '--' : level.toFixed(1) + ' %',
    pressureText: pressure === null ? '--' : pressure.toFixed(2) + ' bar',
    flowText: flow === null ? '--' : flow.toFixed(1) + ' m\u00b3/h',
    pressureColor: pressure !== null && pressure > 6 ? colors.amber : colors.neutral,
    p01, p02, mode, chips, headerRunning: p01.running || p02.running,
    fresh: age !== null && age <= 30,
    flowing: flow !== null && flow > 0.5 && age !== null && age <= 30,
    flowDuration: flow !== null && flow > 0 ? Math.max(0.6, Math.min(3.2, 48 / flow)) : 3.2,
    modeLabel: mode === 'Mode: normal' ? 'Bình thường' : mode === 'Mode: degraded (P02 only)' ? 'Suy giảm' : mode === 'Mode: both pumps running' ? 'Hai bơm chạy' : mode === 'Mode: stopped' ? 'Dừng' : '--',
    modeColor: mode === 'Mode: degraded (P02 only)' ? colors.amber : p01.running || p02.running ? colors.green : colors.gray,
    alarmCount: codes.length,
    alarmColor: codes.some(code => critical.includes(code)) ? colors.red : codes.some(code => warnings.includes(code)) ? colors.amber : colors.neutral,
    updatedText: Number.isFinite(stamp) ? new Date(stamp).toLocaleString('vi-VN', { hour12: false }) : '--',
    freshnessText: age === null ? 'Không có dữ liệu' : 'Dữ liệu: ' + Math.floor(age) + ' s trước',
    freshnessColor: age === null || age > 30 ? colors.red : age >= 10 ? colors.amber : colors.green,
    thresholds: [{value:90,x:448,y:490.6,side:'right'},{value:85,x:253,y:500.9,side:'left'},{value:20,x:253,y:634.8,side:'left'},{value:10,x:448,y:655.4,side:'right'}]
  };
}

// Locate fields by query refId AND column name; frame order is irrelevant.
function readValue(panelData, refId, names) {
  const frames = Array.isArray(panelData?.series) ? panelData.series.filter(frame => frame.refId === refId) : [];
  for (const frame of frames) {
    for (const field of frame.fields || []) {
      if (!names.includes(field.name)) continue;
      const values = field.values;
      const length = values?.length || 0;
      if (!length) continue;
      const value = typeof values.get === 'function' ? values.get(length - 1) : values[length - 1];
      return value === undefined ? null : value;
    }
  }
  return null;
}

function render(root,model){
  if(!root)return;
  const element=id=>root.querySelector('#'+id);
  const text=(id,value)=>{const n=element(id);if(n)n.textContent=value;};
  const attr=(id,key,value)=>{const n=element(id);if(n)n.setAttribute(key,String(value));};
  text('mode',model.modeLabel);attr('mode','fill',model.modeColor);attr('mode-frame','stroke',model.modeColor);
  text('freshness-text',model.freshnessText);attr('freshness-dot','fill',model.freshnessColor);text('updated-text',model.updatedText);
  text('alarm-count','Cảnh báo ('+model.alarmCount+')');attr('alarm-frame','stroke',model.alarmColor);
  text('level-value',model.levelText);attr('level-value','fill',model.level===null?'#b6cadc':model.level>=90||model.level<=10?'#ff536a':model.level>=85||model.level<=20?'#ffcf45':'#27ec63');
  text('pressure-value',model.pressureText);attr('pressure-value','fill',model.pressureText==='--'?'#b6cadc':model.pressureColor==='#b77908'?'#ffcf45':'#27ec63');
  text('flow-value',model.flowText);attr('flow-value','fill',model.flowText==='--'?'#b6cadc':'#27ec63');
  attr('water','y',model.waterY);attr('water','height',model.waterHeight+(model.waterHeight>0?16:0));attr('water-surface','cy',model.waterY);
  attr('water-wave','transform','translate(0 '+model.waterY+')');attr('water-group','visibility',model.waterHeight>0?'visible':'hidden');attr('water-waves','data-moving',model.fresh&&model.level!==null?'true':'false');
  for(const [id,pump]of [['p01',model.p01],['p02',model.p02]]){
    const color=pump.state==='Running'?'#21e66a':pump.state==='Fault'?'#ff435c':'#b5c5d5';
    text(id+'-state',pump.label);attr(id+'-state','fill',color);attr(id+'-frame','stroke',color);attr(id+'-tint','fill',color);
    attr(id+'-rotor','visibility',pump.state==='Running'?'visible':'hidden');attr(id+'-rotor','data-moving',pump.running&&model.fresh?'true':'false');
    attr(id+'-fault','visibility',pump.state==='Fault'?'visible':'hidden');attr(id+'-stop','visibility',pump.state==='Stopped'?'visible':'hidden');attr(id+'-unknown','visibility',pump.state==='--'?'visible':'hidden');
    const moving=pump.running&&model.flowing;attr(id+'-motion','visibility',moving?'visible':'hidden');attr(id+'-motion','data-moving',moving?'true':'false');
    const n=element(id+'-motion');if(n)n.style.animationDuration=model.flowDuration+'s';
  }
  attr('header-motion','visibility',model.flowing?'visible':'hidden');attr('header-motion','data-moving',model.flowing?'true':'false');
  const header=element('header-motion');if(header)header.style.animationDuration=model.flowDuration+'s';
  const group=element('alarm-chips');if(group){group.replaceChildren();const rows=Math.ceil(model.chips.length/3);const startY=938-(rows*24+(rows-1)*8)/2;for(let index=0;index<model.chips.length;index++){
    const chip=model.chips[index],x=641+(index%3)*300,y=startY+Math.floor(index/3)*32;
    const color=chip.color==='#d62f54'?'#ff6a7e':chip.color==='#b77908'?'#ffd15a':'#d2e3ef';
    const box=group.ownerDocument.createElementNS('http://www.w3.org/2000/svg','rect');for(const [k,v]of Object.entries({x,y,width:290,height:24,rx:6,fill:color,'fill-opacity':0.1}))box.setAttribute(k,String(v));
    const label=group.ownerDocument.createElementNS('http://www.w3.org/2000/svg','text');for(const [k,v]of Object.entries({x:x+9,y:y+12,'dominant-baseline':'middle',fill:color,'font-size':13,'font-weight':600}))label.setAttribute(k,String(v));
    if(chip.text.length>35){label.setAttribute('textLength','269');label.setAttribute('lengthAdjust','spacingAndGlyphs');}label.textContent=chip.text;group.append(box,label);
  }}
}

const inputs = {
  level: readValue(data, 'A', ['last_row(val)', 'val']),
  pressure: readValue(data, 'B', ['last_row(val)', 'val']),
  flow: readValue(data, 'C', ['last_row(val)', 'val']),
  p01: readValue(data, 'D', ['last_row(state_code)', 'state_code']),
  p02: readValue(data, 'E', ['last_row(state_code)', 'state_code']),
  alarms: readValue(data, 'F', ['last_row(active_alarms)', 'active_alarms']),
  timestamp: readValue(data, 'G', ['last_row(ts)', 'ts', 'Time']),
  nowMs: Date.now()
};
render(htmlNode, compute(inputs));
